 @GameTest(template="empty")public static void nativeTravelFasterThanGreyWolf(GameTestHelper t){var p=actor(t);var b=boss(t,p);var old=ModEntities.GREY_WOLF.get().create(t.getLevel());old.setNoAi(true);old.setNoGravity(true);old.moveTo(p.position().add(10,0,0));t.getLevel().addFreshEntity(old);b.setSpeed((float)b.getAttributeValue(Attributes.MOVEMENT_SPEED));old.setSpeed((float)old.getAttributeValue(Attributes.MOVEMENT_SPEED));b.setNoAi(false);old.setNoAi(false);var from=b.position();var before=old.position();for(int n=0;n<10;n++){b.setOnGround(true);old.setOnGround(true);b.travel(new Vec3(0,0,1));old.travel(new Vec3(0,0,1));}double distance=b.position().distanceTo(from),wolf=old.position().distanceTo(before);t.assertTrue(distance>wolf*1.2&&distance>0,"native travel speed new="+distance+" wolf="+wolf);System.out.println("VOLKOLAK_NATIVE_TRAVEL_10_STEPS="+distance+" GREY_WOLF="+wolf+"; controller-free native travel fixture");t.succeed();}
 @GameTest(template="empty")public static void earlierExcavationAndConstructionRecovery(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.stage="ESCAPED";e.cinematicDone=true;e.grave=p.blockPosition().offset(2,0,0);var cache=e.grave.below(3);for(int y=-3;y<=0;y++){var pos=e.grave.above(y);e.terrain.put("0:"+y+":0",NbtUtils.writeBlockState(y==0?net.minecraft.world.level.block.Blocks.AIR.defaultBlockState():net.minecraft.world.level.block.Blocks.DIRT.defaultBlockState()));p.serverLevel().setBlockAndUpdate(pos,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());}p.serverLevel().setBlockAndUpdate(cache,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState());t.assertTrue(!VolkolakStory.placeGrave(p.serverLevel(),e)&&!e.placed&&p.level().getBlockState(cache).is(net.minecraft.world.level.block.Blocks.CHEST),"new construction overwritten");p.serverLevel().setBlockAndUpdate(cache,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());t.assertTrue(VolkolakStory.placeGrave(p.serverLevel(),e)&&e.placed&&p.level().getBlockState(cache).is(ModBlocks.CURSED_SKULL_CACHE.get()),"earlier excavation softlock");t.succeed();}
 private static final class Connection extends net.minecraft.network.Connection {private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}public io.netty.channel.Channel channel(){return channel;}}
 private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}public void send(net.minecraft.network.protocol.Packet<?> packet){}public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener){}}
 private static ServerPlayer actor(GameTestHelper t){var p=new ServerPlayer(t.getLevel().getServer(),t.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"CurseProbe"),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);p.moveTo(t.absoluteVec(new Vec3(3,20,3)));p.setNoGravity(true);for(int i=0;i<61;i++)p.tick();t.getLevel().addNewPlayer(p);return p;}
 private static void floor(ServerPlayer p){for(int x=-6;x<=6;x++)for(int z=-6;z<=6;z++){var b=p.blockPosition().offset(x,-1,z);p.serverLevel().setBlockAndUpdate(b,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());for(int y=0;y<5;y++)p.serverLevel().setBlockAndUpdate(b.above(y+1),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());}}
 private static CursedVolkolak boss(GameTestHelper t,ServerPlayer p){var b=ModEntities.CURSED_VOLKOLAK.get().create(t.getLevel());b.moveTo(p.position().add(0,0,-1.4));b.setNoGravity(true);b.setNoAi(true);b.home=b.blockPosition();b.setTarget(p);t.getLevel().addFreshEntity(b);return b;}
 private static void invoke(Object object,String name,Class<?>[] types,Object...values)throws Exception{var m=object.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(object,values);}
 private static void begin(CursedVolkolak b,CursedVolkolak.Move m,LivingEntity target)throws Exception{invoke(b,"begin",new Class<?>[]{CursedVolkolak.Move.class,LivingEntity.class},m,target);}
 private static void tick(CursedVolkolak b,int at)throws Exception{var f=CursedVolkolak.class.getDeclaredField("START");f.setAccessible(true);b.getEntityData().set((net.minecraft.network.syncher.EntityDataAccessor<Integer>)f.get(null),(int)b.level().getGameTime()-at);invoke(b,"act",new Class<?>[]{});}
 private static void active(ServerPlayer p){WolfProgress.data(p).putBoolean("wolf_test_passed",true);for(int i=0;i<3;i++)GreyWolfStory.quest(p,i).putBoolean("Claimed",true);GreyWolfStory.quest(p,3).putBoolean("Accepted",true);}
 private static VolkolakRecords.Encounter record(ServerPlayer p,CursedVolkolak b){var e=new VolkolakRecords.Encounter();e.id=UUID.randomUUID();e.wolf=p.blockPosition();e.anchor=b.blockPosition();e.boss=b.getUUID();e.stage="FIGHT";b.encounter=e.id;VolkolakRecords.get(p.serverLevel()).encounters.put(e.id,e);GreyWolfStory.quest(p,3).putUUID("Encounter",e.id);GreyWolfStory.quest(p,3).putString("Phase","FIGHT");return e;}
 private static ItemStack skull(ServerPlayer p,VolkolakRecords.Encounter e,UUID owner){var nonce=UUID.randomUUID();e.issues.put(owner,nonce);var item=new ItemStack(ModItems.CURSED_VOLKOLAK_SKULL.get());var n=new CompoundTag();n.putUUID("Owner",owner);n.putUUID("Encounter",e.id);n.putUUID("Nonce",nonce);n.putString("Dimension","minecraft:overworld");item.set(DataComponents.CUSTOM_DATA,CustomData.of(n));return item;}
 private static GreyWolf npc(GameTestHelper t,ServerPlayer p)throws Exception{var w=ModEntities.GREY_WOLF.get().create(t.getLevel());w.moveTo(p.position().add(2,0,0));w.setNoGravity(true);w.debug(true);t.getLevel().addFreshEntity(w);w.start(p);var f=GreyWolf.class.getDeclaredField("CLOCK");f.setAccessible(true);w.getEntityData().set((net.minecraft.network.syncher.EntityDataAccessor<Long>)f.get(null),w.level().getGameTime()-30);w.tick();w.finish();w.getEntityData().set((net.minecraft.network.syncher.EntityDataAccessor<Long>)f.get(null),w.level().getGameTime()-160);w.tick();return w;}

 @GameTest(template="empty")public static void distinctRegistryAndEgg(GameTestHelper t){var p=actor(t);var b=boss(t,p);var old=ModEntities.VOLKOLAK.get().create(t.getLevel());t.assertTrue(b.getMaxHealth()==400&&old.getMaxHealth()==165&&b.getType()!=old.getType(),"old mob replaced");t.assertTrue(((SpawnEggItem)ModItems.CURSED_VOLKOLAK_SPAWN_EGG.get()).getType(new ItemStack(ModItems.CURSED_VOLKOLAK_SPAWN_EGG.get()))==b.getType(),"egg type");t.assertTrue(b.encounter==null&&GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.LOCKED,"egg quest pollution");t.succeed();}
 @GameTest(template="empty")public static void versionMigrationAndAllClaims(GameTestHelper t){var p=actor(t);WolfProgress.data(p).putBoolean("wolf_test_passed",true);GreyWolfStory.data(p).putInt("Version",1);GreyWolfStory.quest(p,0).putInt("Progress",7);GreyWolfStory.quest(p,2).putBoolean("Claimed",true);t.assertTrue(GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.LOCKED,"skipped prerequisites");GreyWolfStory.quest(p,0).putBoolean("Claimed",true);GreyWolfStory.quest(p,1).putBoolean("Claimed",true);t.assertTrue(GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.OFFERED&&GreyWolfStory.data(p).getInt("Version")==2&&GreyWolfStory.quest(p,0).getInt("Progress")==7,"migration reset");t.succeed();}
 @GameTest(template="empty")public static void badBloodNativeHealAndInstant(GameTestHelper t){var p=actor(t);p.setHealth(4);BadBlood.apply(p,p);p.heal(4);t.assertTrue(p.getHealth()==6,"gradual heal not halved");MobEffects.HEAL.value().applyInstantenousEffect(p,p,p,0,1);t.assertTrue(p.getHealth()==10,"instant heal halved");MobEffects.HEAL.value().applyEffectTick(p,0);t.assertTrue(p.getHealth()==14,"drink tick instant halved");p.removeEffect(ModEffects.BAD_BLOOD);p.heal(4);t.assertTrue(p.getHealth()==18,"milk/remove did not restore heal");t.succeed();}
 @GameTest(template="empty")public static void badBloodNativeFoodOddRemainder(GameTestHelper t){var p=actor(t);p.getFoodData().setFoodLevel(10);p.getFoodData().setSaturation(0);BadBlood.apply(p,p);var food=new FoodProperties.Builder().nutrition(3).saturationModifier(.5F).build();p.eat(p.level(),new ItemStack(Items.APPLE),food);t.assertTrue(p.getFoodData().getFoodLevel()==11&&p.getFoodData().getSaturationLevel()==1.5F,"food delta");p.eat(p.level(),new ItemStack(Items.APPLE),food);t.assertTrue(p.getFoodData().getFoodLevel()==13&&p.getFoodData().getSaturationLevel()==3,"odd carry");p.removeEffect(ModEffects.BAD_BLOOD);t.assertTrue(!p.getPersistentData().contains("VolkolakFoodHalf"),"fraction remained");t.succeed();}
 @GameTest(template="empty")public static void badBloodRefreshNoHealthOrDot(GameTestHelper t){var p=actor(t);BadBlood.apply(p,p);BadBlood.apply(p,p);float hp=p.getHealth();for(int i=0;i<45;i++)((MobEffect)ModEffects.BAD_BLOOD.value()).applyEffectTick(p,0);t.assertTrue(p.getHealth()==hp&&p.getMaxHealth()==20&&p.getEffect(ModEffects.BAD_BLOOD).getDuration()==500&&p.getEffect(ModEffects.BAD_BLOOD).getAmplifier()==0,"Bad Blood became DOT or stacking");t.succeed();}
 @GameTest(template="empty")public static void clawActualDamageAndSharedBleed(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);begin(b,CursedVolkolak.Move.CLAW_L,p);tick(b,10);t.assertTrue(p.getHealth()==11&&p.hasEffect(ModEffects.WOLF_CUT)&&!p.hasEffect(ModEffects.BAD_BLOOD),"claw native hit/bleed");t.succeed();}
 @GameTest(template="empty")public static void shieldNoBleedOrGrab(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);p.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));p.setYRot(180);p.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);for(int i=0;i<6;i++)p.doTick();p.setYHeadRot(180);t.assertTrue(p.isBlocking(),"fixture shield startup");begin(b,CursedVolkolak.Move.GRAB,p);tick(b,22);t.assertTrue(!p.isPassenger()&&p.getHealth()==20&&!p.hasEffect(ModEffects.BAD_BLOOD)&&!p.hasEffect(ModEffects.WOLF_CUT)&&b.move()==CursedVolkolak.Move.STAGGER,"shield grab landed hp="+p.getHealth()+" state="+b.move()+" blocking="+p.isBlocking()+" yaw="+p.getYHeadRot());t.succeed();}
 @GameTest(template="empty")public static void grabOneBiteAndFiniteRelease(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);begin(b,CursedVolkolak.Move.GRAB,p);tick(b,22);t.assertTrue(p.getVehicle()==b&&b.upright(),"native mount capture failed");tick(b,28);t.assertTrue(p.getHealth()==4&&p.hasEffect(ModEffects.BAD_BLOOD),"grab bite damage/effect hp="+p.getHealth()+" held="+b.heldEntity()+" vehicle="+p.getVehicle()+" dist="+b.distanceTo(p));tick(b,29);t.assertTrue(p.getHealth()==4,"extra bite");for(int i=0;i<20;i++)b.tick();t.assertTrue(!p.isPassenger()&&b.heldEntity()==-1&&!p.getPersistentData().contains("VolkolakHolder"),"indefinite hold");t.succeed();}
 @GameTest(template="empty")public static void grabRoofAndRemovalCleanup(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);p.serverLevel().setBlockAndUpdate(b.blockPosition().above(2),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());begin(b,CursedVolkolak.Move.GRAB,p);tick(b,22);t.assertTrue(!p.isPassenger(),"capture under low roof");p.serverLevel().setBlockAndUpdate(b.blockPosition().above(2),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());tick(b,23);t.assertTrue(p.isPassenger(),"capture");b.discard();t.assertTrue(!p.isPassenger()&&!p.getPersistentData().contains("VolkolakHeldUntil"),"remove hold leak");t.succeed();}
 @GameTest(template="empty")public static void nativeWallBlocksClaw(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);b.moveTo(p.position().add(0,0,-2.5));var wall=p.blockPosition().offset(0,0,-1);for(int y=0;y<4;y++)p.serverLevel().setBlockAndUpdate(wall.above(y),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState());begin(b,CursedVolkolak.Move.CLAW_L,p);tick(b,10);t.assertTrue(p.getHealth()==20&&!p.hasEffect(ModEffects.WOLF_CUT),"damage through wall");t.succeed();}
 @GameTest(template="empty")public static void questNativeLethalNoDeathReward(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);b.setHealth(10);b.hurt(p.damageSources().playerAttack(p),10000);t.assertTrue(b.isAlive()&&b.getHealth()==1&&b.move()==CursedVolkolak.Move.ESCAPE&&e.stage.equals("ESCAPED")&&!e.cinematicDone,"native lethal clamp");t.assertTrue(!GreyWolfStory.quest(p,3).getBoolean("Ready"),"combat awarded bow");t.succeed();}
 @GameTest(template="empty")public static void eggBossOrdinaryDeathNoStory(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);b.hurt(p.damageSources().playerAttack(p),10000);t.assertTrue(!b.isAlive()&&!GreyWolfStory.quest(p,3).getBoolean("Ready")&&!GreyWolfStory.quest(p,3).hasUUID("Encounter"),"egg completed quest");t.succeed();}
 @GameTest(template="empty")public static void foreignSkullAndNonceRejected(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);GreyWolfStory.quest(p,3).putString("Phase","RETURN");p.getInventory().setItem(0,skull(p,e,UUID.randomUUID()));t.assertTrue(!VolkolakStory.handOver(p),"foreign skull consumed");var own=skull(p,e,p.getUUID());e.issues.put(p.getUUID(),UUID.randomUUID());p.getInventory().setItem(1,own);t.assertTrue(!VolkolakStory.handOver(p)&&!GreyWolfStory.quest(p,3).getBoolean("Ready"),"forged nonce");t.succeed();}
 @GameTest(template="empty")public static void handoverAndAtomicTwoRewards(GameTestHelper t)throws Exception{var p=actor(t);var w=npc(t,p);active(p);var b=boss(t,p);var e=record(p,b);e.wolf=w.home();GreyWolfStory.quest(p,3).putString("Phase","RETURN");p.getInventory().setItem(0,skull(p,e,p.getUUID()));t.assertTrue(GreyWolfStory.action(p,w,3,4)&&GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.REWARD_READY&&e.stage.equals("RESOLVED")&&p.getInventory().getItem(0).isEmpty(),"physical handover");for(int i=0;i<p.getInventory().getContainerSize();i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));p.getInventory().setItem(0,ItemStack.EMPTY);t.assertTrue(!GreyWolfStory.action(p,w,3,2)&&!GreyWolfStory.quest(p,3).getBoolean("Claimed")&&p.getInventory().getItem(0).isEmpty(),"partial bow-only reward");p.getInventory().setItem(1,ItemStack.EMPTY);t.assertTrue(GreyWolfStory.action(p,w,3,2)&&GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.COMPLETED&&!GreyWolfStory.action(p,w,3,2),"atomic claim/replay");t.succeed();}
 @GameTest(template="empty")public static void storageNotLossDestructionIsLoss(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);var item=skull(p,e,p.getUUID());p.getInventory().setItem(0,ItemStack.EMPTY);t.assertTrue(e.issues.containsKey(p.getUUID()),"out of inventory counted lost");var entity=new net.minecraft.world.entity.item.ItemEntity(p.level(),p.getX(),p.getY(),p.getZ(),item);VolkolakEvents.lost(entity);t.assertTrue(!e.issues.containsKey(p.getUUID()),"proven loss not recoverable");t.succeed();}
 @GameTest(template="empty")public static void saveWorldProvenanceAndSkullNonce(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.grave=p.blockPosition().offset(120,0,0);e.placed=true;e.stage="ESCAPED";e.participants.put(p.getUUID(),p.level().getGameTime());var item=skull(p,e,p.getUUID());var saved=VolkolakRecords.get(p.serverLevel()).save(new CompoundTag(),p.registryAccess());var again=VolkolakRecords.load(saved).encounters.get(e.id);t.assertTrue(again.boss.equals(b.getUUID())&&again.grave.equals(e.grave)&&again.issues.equals(e.issues)&&again.participants.equals(e.participants),"world record roundtrip");var copied=ItemStack.parseOptional(p.registryAccess(),(CompoundTag)item.save(p.registryAccess()));t.assertTrue(copied.get(DataComponents.CUSTOM_DATA).copyTag().equals(item.get(DataComponents.CUSTOM_DATA).copyTag()),"skull native NBT");t.succeed();}
 @GameTest(template="empty")public static void snapshotNoExactTargetOrNonce(GameTestHelper t)throws Exception{var p=actor(t);var w=npc(t,p);active(p);var b=boss(t,p);var e=record(p,b);e.grave=p.blockPosition().offset(110,0,30);skull(p,e,p.getUUID());var q=GreyWolfStory.quest(p,3);q.putLong("Hint",VolkolakStory.hint(e.grave,142,65,105).asLong());var snap=GreyWolfStory.snapshot(p,w).getList("Quests",10).getCompound(3);t.assertTrue(!snap.hasUUID("Encounter")&&!snap.hasUUID("Target")&&!snap.hasUUID("Nonce")&&!snap.contains("Grave")&&!snap.contains("Rewards")&&snap.contains("Phase"),"snapshot leaked");t.succeed();}
 @GameTest(template="empty")public static void nativeBuriedCacheRequiresExcavationAndOwner(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.stage="ESCAPED";e.cinematicDone=true;e.placed=true;e.grave=p.blockPosition().offset(2,0,0);var pos=e.grave.below(3);p.moveTo(pos.getX()+.5,pos.getY()+3,pos.getZ()+.5);for(int y=1;y<=2;y++)p.serverLevel().setBlockAndUpdate(pos.above(y),net.minecraft.world.level.block.Blocks.DIRT.defaultBlockState());p.serverLevel().setBlockAndUpdate(pos,ModBlocks.CURSED_SKULL_CACHE.get().defaultBlockState());t.assertTrue(!VolkolakStory.cache(p,pos)&&!e.issues.containsKey(p.getUUID()),"buried cache issued skull");for(int y=1;y<=3;y++)p.serverLevel().setBlockAndUpdate(pos.above(y),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());t.assertTrue(VolkolakStory.cache(p,pos)&&!VolkolakStory.cache(p,pos)&&VolkolakStory.phase(p).equals("RETURN"),"native exposed cache claim/replay");var item=p.getInventory().items.stream().filter(v->v.is(ModItems.CURSED_VOLKOLAK_SKULL.get())).findFirst().orElseThrow();var tag=item.get(DataComponents.CUSTOM_DATA).copyTag();t.assertTrue(tag.getUUID("Owner").equals(p.getUUID())&&tag.getUUID("Nonce").equals(e.issues.get(p.getUUID())),"skull binding");t.succeed();}
 @GameTest(template="empty")public static void cacheNeverOverwritesChestOrExistingSoil(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.stage="ESCAPED";e.placed=true;e.cinematicDone=true;e.grave=p.blockPosition().offset(2,0,0);var cache=e.grave.below(3);for(int y=0;y<3;y++)p.serverLevel().setBlockAndUpdate(cache.above(y),net.minecraft.world.level.block.Blocks.DIRT.defaultBlockState());VolkolakStory.placeGrave(p.serverLevel(),e);t.assertTrue(p.level().getBlockState(cache).is(net.minecraft.world.level.block.Blocks.DIRT),"overwrote soil");for(int y=0;y<3;y++)p.serverLevel().setBlockAndUpdate(cache.above(y),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());p.serverLevel().setBlockAndUpdate(cache,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState());VolkolakStory.placeGrave(p.serverLevel(),e);t.assertTrue(p.level().getBlockState(cache).is(net.minecraft.world.level.block.Blocks.CHEST),"overwrote chest");p.serverLevel().setBlockAndUpdate(cache,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());VolkolakStory.placeGrave(p.serverLevel(),e);t.assertTrue(p.level().getBlockState(cache).is(ModBlocks.CURSED_SKULL_CACHE.get()),"excavated air did not materialise cache");t.succeed();}
 @GameTest(template="empty")public static void fullBagSkullClaimIsRetryable(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.stage="ESCAPED";e.placed=true;e.cinematicDone=true;e.grave=p.blockPosition().offset(2,0,0);var pos=e.grave.below(3);p.moveTo(pos.getX()+.5,pos.getY()+3,pos.getZ()+.5);p.serverLevel().setBlockAndUpdate(pos,ModBlocks.CURSED_SKULL_CACHE.get().defaultBlockState());for(int y=1;y<=3;y++)p.serverLevel().setBlockAndUpdate(pos.above(y),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());for(int i=0;i<p.getInventory().getContainerSize();i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));t.assertTrue(!VolkolakStory.cache(p,pos)&&!e.issues.containsKey(p.getUUID()),"full bag consumed issue");p.getInventory().setItem(0,ItemStack.EMPTY);t.assertTrue(VolkolakStory.cache(p,pos),"full bag retry");t.succeed();}
 @GameTest(template="empty")public static void resolvedWorldAllowsPersonalInvestigationWithoutBossClone(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);e.stage="RESOLVED";e.cinematicDone=true;e.placed=true;e.grave=p.blockPosition().offset(120,0,0);GreyWolfStory.quest(p,3).putString("Phase","TRACK");VolkolakStory.ensure(p,e.wolf);t.assertTrue(VolkolakStory.phase(p).equals("FIND_CURSE")&&!GreyWolfStory.quest(p,3).getBoolean("Ready")&&e.boss.equals(b.getUUID()),"late participant blocked or awarded/cloned");t.succeed();}
 @GameTest(template="empty")public static void skullPickupOwnerAndExtendedLifetime(GameTestHelper t){var p=actor(t);active(p);var b=boss(t,p);var e=record(p,b);var foreign=UUID.randomUUID();var item=skull(p,e,foreign);var entity=new net.minecraft.world.entity.item.ItemEntity(p.level(),p.getX(),p.getY(),p.getZ(),item);var pickup=new net.neoforged.neoforge.event.entity.player.ItemEntityPickupEvent.Pre(p,entity);VolkolakEvents.pickup(pickup);t.assertTrue(pickup.canPickup()==net.neoforged.neoforge.common.util.TriState.FALSE,"foreign pickup");var expires=new net.neoforged.neoforge.event.entity.item.ItemExpireEvent(entity);expires.setExtraLife(100);VolkolakEvents.expired(expires);t.assertTrue(e.issues.containsKey(foreign),"extended lifetime counted lost");t.succeed();}
 @GameTest(template="empty")public static void phaseTransitionRetainsGrabCooldownAndSpeed(GameTestHelper t)throws Exception{var p=actor(t);floor(p);var b=boss(t,p);begin(b,CursedVolkolak.Move.GRAB,p);b.setHealth(90);b.tick();var field=CursedVolkolak.class.getDeclaredField("cooldowns");field.setAccessible(true);var cooldown=(Map<?,?>)field.get(b);t.assertTrue(b.phase()==3&&b.move()==CursedVolkolak.Move.ROAR&&((Integer)cooldown.get(CursedVolkolak.Move.GRAB))>=479&&Math.abs(b.getAttributeValue(Attributes.MOVEMENT_SPEED)-.378*1.12)<.0001,"phase reset cooldown or missed speed");t.succeed();}

